353	__global__ void __launch_bounds__(SG_VIT_TC_MEGA_BLOCK)
354	fused_vit_megakernel_tc(PersistentContext ctx,
355	                        float* __restrict__ params,
356	                        ViTInputCtx in,
357	                        float* __restrict__ grad,
358	                        float lr, int step, FusedOptState st) {
359	    __shared__ VitTcSmem sm;
360	    GridBarrier bar = ctx.barrier();
361	    const int cta = blockIdx.x;
362	    const int nCTA = (int)ctx.n_ctas;
363	    const int B = in.B;
364	    const int T = B * vit::kSeq;
365	    const int Tp = B * vit::kNPatch;
366	
367	    // Workspace partition.
368	    float* ws = in.workspace;
369	    const int64_t acts_f = vit_tc_acts_floats(T, B);
370	    __nv_bfloat16* acts_base = reinterpret_cast<__nv_bfloat16*>(ws);
371	    float* scratch_base = ws + acts_f;
372	    const int64_t scratch_per = vittc::vit_tile_scratch_total_f32();
373	    float* lnvec_base = scratch_base + (int64_t)nCTA * scratch_per;
374	    float* loss_part  = lnvec_base + (int64_t)nCTA * vittc::kLnVecElems;
375	    float* loss_out   = loss_part + nCTA;
376	
377	    vittc::VitActs acts = vittc::vit_acts_bind(acts_base, T, B);
378	    vittc::VitTileScratch sc = vittc::vit_tile_scratch_bind(scratch_base + (int64_t)cta * scratch_per);
379	    float* my_lnvec = lnvec_base + (int64_t)cta * vittc::kLnVecElems;
380	
381	    VitWeights w = vit_bind(params);
382	
383	    // ── P0: zero this CTA's LN-vec partials + loss slot (dW/cls/pos/patch grads
384	    //    are written-once → no pre-zero). ──
385	    for (int i = threadIdx.x; i < vittc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
386	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
387	    bar.sync();   // B0
388	
389	    // ── P1: token-tile-parallel fwd+bwd. Each CTA grid-strides over tiles of
390	    //    kTileM rows; for its tile it runs fwd (→ acts X, NLL) then bwd (→ acts
391	    //    dY, dh0, LN-vec partials). Barrier-free within the tile. ──
392	    const int nrows_tile = vittc::kTileM;
393	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
394	    float nll_acc = 0.0f;
395	    for (int ti = cta; ti < n_tiles; ti += nCTA) {
396	        const int g0 = ti * nrows_tile;
397	        const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
398	        float nll = vittc::vittc_forward_tile(w, g0, nrows, acts, sc, in.patches, in.targets,
399	                                              sm.sA, sm.sB, sm.red);
400	        vittc::vittc_backward_tile(w, g0, nrows, B, acts, sc, in.targets,
401	                                   my_lnvec, sc.work2, sm.sA, sm.sB, sm.red);
402	        if (threadIdx.x == 0) nll_acc += nll;
403	        __syncthreads();
404	    }
405	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
406	    bar.sync();   // B1: all acts (X + dY) + LN-vec partials complete
407	
408	    // ── P2: assemble all 32 grads into `grad`. dW output-stationary (gt % nCTA),
409	    //    biases, cls/pos owner-scan, LN-vec reduce. No partials. The 10 dW specs
410	    //    are built into SHARED smem (thread 0; identical for all). ──
411	    if (threadIdx.x == 0) vittc::vittc_build_dw_specs(acts, B, T, Tp, sm.spec);
412	    __syncthreads();
413	    vittc::VitDwSpec* spec = sm.spec;
414	    const int n_dw = vittc::vittc_dw_total_tiles<SG_TUNED_TILE_N>(spec);
415	    for (int gt = cta; gt < n_dw; gt += nCTA)
416	        vittc::vittc_dw_run_tile<SG_TUNED_TILE_N>(spec, gt, acts.dh0, grad, sm.sA, sm.sB);
417	    vittc::vittc_dw_biases(spec, acts.dh0, grad);
418	    vittc::vittc_clspos_owner_scan(acts, T, grad, cta, nCTA);
419	    vittc::vittc_lnvec_reduce(lnvec_base, grad, nCTA, cta);
420	    // Loss reduce (fp64) by CTA 0.
421	    if (cta == 0 && threadIdx.x == 0) {
422	        double s = 0.0;
423	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
424	        *in.loss_out = (float)(s / (double)B);
425	    }
426	    (void)loss_out;
427	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue
428	
429	    // ── P3: scalar optimizer tail over the reduced grad (REUSED verbatim). ──
430	    st.lr = lr;
431	    {
432	        __shared__ int task_slot;
433	        TaskQueue q = ctx.queue();
434	        for (int t = q.next_block(&task_slot); t < kVitNumTensors;
435	             t = q.next_block(&task_slot)) {
436	            const int n = kVitSizes[t];
437	            const int64_t off = (int64_t)kVitOffsets[t];
438	            const FusedOptState ts = vit_rebase_state<Opt>(st, off);
439	            float* __restrict__ p = params + off;
440	            const float* __restrict__ gg = grad + off;
441	            for (int i = threadIdx.x; i < n; i += blockDim.x)
442	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
443	        }
444	    }
445	}
