447	// ncta_cap (default 0): if >0, launch min(n_sms, ncta_cap) CTAs instead of one
448	// per SM. The grid barrier rendezvous is over the LAUNCHED count (ctx.n_ctas);
449	// any cap is hang-safe as long as the workspace + dW-tile/cls/pos ownership use
450	// the SAME nCTA (they read ctx.n_ctas). The shipped path passes 0 (full
451	// saturation); a memory-constrained TEST passes a small cap so the per-CTA
452	// scratch (nCTA × slab) fits. Determinism is preserved per fixed nCTA.
453	template <OptId Opt>
454	cudaError_t launch_fused_vit_megakernel_tc(
455	        PersistentContext ctx, float* params, ViTInputCtx in,
456	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
457	        int ncta_cap = 0) {
458	    int dev = 0;
459	    cudaError_t err = cudaGetDevice(&dev);
460	    if (err != cudaSuccess) return err;
461	    int n_sms = 0;
462	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
463	    if (err != cudaSuccess) return err;
464	
465	    // Hang-freedom: certify one block/SM occupancy with the ACTUAL dynamic smem
466	    // (0 here — VitTcSmem is static). If the static smem + 200-reg consumer can't
467	    // place one block/SM, REFUSE (the grid barrier would hang).
468	    int occ = 0;
469	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
470	        &occ, (const void*)&fused_vit_megakernel_tc<Opt>, SG_VIT_TC_MEGA_BLOCK,
471	        /*dynamicSMemBytes=*/0);
472	    if (err != cudaSuccess) return err;

680	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) {
681	            const int r = idx / vit::kD, j = idx % vit::kD;
682	            sc.work[(int64_t)r * vit::kD + j] += sc.x1[(int64_t)r * vit::kD + j] + L.ff2_b[j];
683	        }
684	        __syncthreads();
685	        if (li + 1 < vit::kLayers) {
686	            // n2(r2) → finalin (fp32 reused) + n2 caches[li]; bf16 → X_in[li+1].
687	            vittc_ln_fwd_tile(sc.work, L.n2_w, L.n2_b, nrows, sc.finalin, sc.n2x[li], sc.n2i[li], red);
688	            for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) {
689	                const int r = idx / vit::kD, j = idx % vit::kD;
690	                acts.X_in[li + 1][(int64_t)(g0 + r) * vit::kD + j] = __float2bfloat16(sc.finalin[(int64_t)r * vit::kD + j]);
691	            }
692	            __syncthreads();
693	        } else {
694	            // last layer: n2(r2) → finalin (fp32, all positions; head reads pos 0).
695	            vittc_ln_fwd_tile(sc.work, L.n2_w, L.n2_b, nrows, sc.finalin, sc.n2x[li], sc.n2i[li], red);
696	        }
697	    }
698	
699	    // ── Final norm + head + CE, scalar PER-SAMPLE on the CLS position (0) only.
700	    //    DELTA 3: CLS at pos 0 (row si*kSeq), not the last position. ──
701	    float nll_acc = 0.0f;
702	    for (int si = 0; si < nsamp; ++si) {
703	        const int rcls = si * vit::kSeq;                  // CLS row (pos 0)
704	        const float* hcls = sc.finalin + (int64_t)rcls * vit::kD;
705	        float sum = 0.0f;
706	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) sum += hcls[j];
707	        float mean = vit_block_sum(sum, red) / (float)vit::kD;
708	        float vs = 0.0f;
709	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) { float c = hcls[j] - mean; vs += c * c; }
710	        float var = vit_block_sum(vs, red) / (float)vit::kD;
711	        float iv = rsqrtf(var + vit::kLnEps);
712	        if (threadIdx.x == 0) sc.fni[rcls] = iv;
713	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
