// COALESCED variant for operands whose CONTIGUOUS HBM dimension is `mn` (the
// row index of the staged tile), e.g. the dW operands dY[k*Nout+m] / X[k*Kin+n]
// (layout [K, MN] → mn is contiguous). The default stage_kmajor_tile maps
// consecutive threads to consecutive k (stride-MN, UNCOALESCED for [K,MN]). Here
// consecutive threads map to consecutive mn → consecutive HBM addresses → 128B
// coalesced loads. The smem dst formula (and thus the staged tile content) is
// BIT-IDENTICAL — only WHICH thread writes WHICH (mn,k) changes — so the wgmma
// operands are unchanged (parity-safe by construction). Used by the dW path only;
// fwd's X[m*K+k] is already k-contiguous and stays on the default mapping.
template <int MN, typename Src>
__device__ __forceinline__ void stage_kmajor_tile_mmajor(
        __nv_bfloat16* smem_tile, int kbase, Src src, int t0, int nthreads) {
    #pragma unroll 1
    for (int i = t0; i < MN * wgs::kWgmmaAtomK; i += nthreads) {
        const int k  = i / MN;                 // mn-FAST: consecutive threads → mn
        const int mn = i % MN;
        const int dst = (k >> 3) * (MN * 8) + mn * 8 + (k & 7);
        smem_tile[dst] = src(mn, kbase + k);
    }
}

// ════════════════════════════════════════════════════════════════════════
//  COALESCED dW GEMM (kind==0): D[Nout,N] = Σ_k dY[k,Nout]·X[k,N], ONE 64×N
//  m-atom (mbase..mbase+64). Same ascending-k fp32 accumulation + single-CTA
//  ownership + k-major smem layout as tc_gemm_block_unpipelined, but stages both
//  operands with the m-major COALESCED mapping (dY/X are [K,MN], mn contiguous).
//  This is the dW-specific lever: the dW K=T=278528 contraction was the dominant
//  P2 sub-phase and its uncoalesced stride-Nout staging dominated each ~4µs
//  k-step (the wgmma itself is ~3% of that). N is the compile-time wgmma atom
//  width. Determinism: ascending-k, one CTA owns the tile, no atomics.
// ════════════════════════════════════════════════════════════════════════
template <int N, typename SrcA, typename SrcB, typename Out>
__device__ __forceinline__ void tc_gemm_dw_coalesced(
        int mbase, int n_real, int k_steps,
        SrcA srcA, SrcB srcB, Out out,
        __nv_bfloat16* smemA, __nv_bfloat16* smemB) {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
    const int tid = threadIdx.x;
    const int nthreads = blockDim.x;
    const bool in_wg0 = (tid < 128);
    const int tid_wg = tid & 127;
    wgs::WgmmaAccum<N> acc;
    if (in_wg0) wgs::wgmma_fence();
    #pragma unroll 1
    for (int k = 0; k < k_steps; ++k) {
        stage_kmajor_tile_mmajor<wgs::kWgmmaAtomM>(
            smemA, k * wgs::kWgmmaAtomK,
            [&] (int mn, int kk) { return srcA(mbase + mn, kk); },
            tid, nthreads);
        stage_kmajor_tile_mmajor<N>(
            smemB, k * wgs::kWgmmaAtomK,
            [&] (int mn, int kk) { return srcB(mn, kk); },
            tid, nthreads);
        __syncthreads();
        if (in_wg0) {
            wgs::SmemDesc dA = wgs::make_desc_A_kmajor<wgs::kWgmmaAtomM, wgs::kSwizzleNone>(smemA);
            wgs::SmemDesc dB = wgs::make_desc_B_kmajor<N, wgs::kSwizzleNone>(smemB);
            if (k == 0) wgs::wgmma_m64nNk16_bf16<N, /*ScaleD=*/0, 0, 0>(acc, dA, dB);
